    ('canonical_volume_trx_share_windowed_region_include_synthetic', $kpi$SELECT SUM(bm.value) FILTER (WHERE bm.brand::text = $1) / NULLIF(SUM(bm.value), 0) AS share, MAX(bm.metric_date) AS data_month, (MAX(bm.metric_date) + INTERVAL '1 month' - INTERVAL '1 day')::date AS data_through, COUNT(DISTINCT bm.metric_date) AS months_in_window FROM (SELECT * FROM business_metrics WHERE brand IS NOT NULL AND region IS NOT NULL) bm WHERE bm.metric_type = 'trx' AND bm.metric_date >= $3::date AND (bm.metric_date + INTERVAL '1 month' - INTERVAL '1 day')::date <= $4::date AND bm.metric_date < date_trunc('month', CURRENT_DATE)::date AND LOWER(bm.region::text) = LOWER($2)$kpi$, 4, $note$canonical TRx lane: brand TRx / portfolio TRx summed over complete months fully inside [start, end] over business_metrics for the specified region; $1 brand (required), $2 region, $3 start, $4 end; includes synthetic (showcase)$note$),
